-- Critical security remediation: prevent public URL downloads from bypassing Storage RLS.
-- The library-media bucket must be private; published assets are served via signed URLs
-- generated by the app and constrained by the existing "library media read published assets" policy.
update storage.buckets
set public = false
where id = 'library-media';

-- Remove the legacy broad read policy if it still exists.
drop policy if exists "library media read" on storage.objects;

-- Reassert the published-assets-only policy for authenticated app sessions.
drop policy if exists "library media read published assets" on storage.objects;
create policy "library media read published assets"
on storage.objects
for select
to authenticated
using (
  bucket_id = 'library-media'
  and (
    has_role(auth.uid(), 'admin'::app_role)
    or exists (
      select 1
      from public.library_audios as a
      where a.published is true
        and (a.audio_url = objects.name or a.cover_url = objects.name)
    )
    or exists (
      select 1
      from public.library_images as i
      where i.published is true
        and i.image_url = objects.name
    )
  )
);
